def is_palindrome(n):
    """Checks if a number is a palindrome."""
    return str(n) == str(n)[::-1]

def get_palindrome_products(min_factor, max_factor):
    """
    Helper function to generate all palindrome products and their factors
    within the given range [min_factor, max_factor].
    """
    palindrome_products = {}
    for i in range(min_factor, max_factor + 1):
        for j in range(i, max_factor + 1): # j starts from i to avoid duplicate pairs (a,b) and (b,a)
            product = i * j
            if is_palindrome(product):
                if product not in palindrome_products:
                    palindrome_products[product] = set()
                # Store factors as a tuple (i, j) for consistency and to allow storage in a set
                palindrome_products[product].add((i, j))
    return palindrome_products

def largest(min_factor, max_factor):
    """Given a range of numbers, find the largest palindromes which
       are products of two numbers within that range.

    :param min_factor: int with a default value of 0
    :param max_factor: int
    :return: tuple of (palindrome, iterable).
             Iterable should contain both factors of the palindrome in an arbitrary order.
    """
    if min_factor > max_factor:
        raise ValueError("min must be <= max")

    palindrome_products = get_palindrome_products(min_factor, max_factor)

    if not palindrome_products:
        return (None, [])

    max_palindrome_value = max(palindrome_products.keys())
    # Convert the set of factor tuples to a sorted list of factor tuples
    # Sorting ensures a consistent order of factor pairs in the output iterable.
    factors = sorted(list(palindrome_products[max_palindrome_value]))

    return (max_palindrome_value, factors)


def smallest(min_factor, max_factor):
    """Given a range of numbers, find the smallest palindromes which
    are products of two numbers within that range.

    :param min_factor: int with a default value of 0
    :param max_factor: int
    :return: tuple of (palindrome, iterable).
    Iterable should contain both factors of the palindrome in an arbitrary order.
    """
    if min_factor > max_factor:
